#include "api/output_projection_training_api.h"
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <vector>
int main(){constexpr std::uint32_t H=5,T=7,R=4;constexpr float lr=.01f,b1=.8f,b2=.9f,eps=1e-5f,decay=.03f;std::vector<float>w(H*H),a(T*H),u(T*H),g(H*H,0);for(size_t i=0;i<w.size();++i)w[i]=std::sin(i*.13f);for(size_t i=0;i<a.size();++i)a[i]=std::cos(i*.17f);for(size_t i=0;i<u.size();++i)u[i]=std::sin(i*.07f);for(std::uint32_t h=0;h<H;++h)for(std::uint32_t o=0;o<H;++o)for(std::uint32_t t=0;t<R;++t)g[h*H+o]+=a[t*H+h]*u[t*H+o];auto refw=w,refm=std::vector<float>(w.size()),refv=refm;auto adam=[&](std::uint64_t s){for(size_t i=0;i<w.size();++i){refm[i]=b1*refm[i]+(1-b1)*g[i];refv[i]=b2*refv[i]+(1-b2)*g[i]*g[i];float mh=refm[i]/(1-std::pow(b1,float(s))),vh=refv[i]/(1-std::pow(b2,float(s)));refw[i]=(1-lr*decay)*refw[i]-lr*mh/(std::sqrt(vh)+eps);}};auto*x=spaceslug_output_projection_training_create(w.data(),H,T);if(!x)return 1;adam(1);if(spaceslug_output_projection_training_adamw_step(x,a.data(),u.data(),R,lr,b1,b2,eps,decay)!=0)return 1;std::vector<float>rw(w.size()),rg(w.size()),rm(w.size()),rv(w.size());std::uint64_t step=0;if(spaceslug_output_projection_training_readback_adamw_state(x,rw.data(),rg.data(),rm.data(),rv.data(),&step)!=0||step!=1)return 1;auto cw=rw,cm=rm,cv=rv;float e1=0;for(size_t i=0;i<w.size();++i)e1=std::max({e1,std::abs(rw[i]-refw[i]),std::abs(rm[i]-refm[i]),std::abs(rv[i]-refv[i])});adam(2);if(spaceslug_output_projection_training_adamw_step(x,a.data(),u.data(),R,lr,b1,b2,eps,decay)!=0)return 1;std::vector<float>uninterrupted(w.size());if(spaceslug_output_projection_training_readback_adamw_state(x,uninterrupted.data(),rg.data(),rm.data(),rv.data(),&step)!=0||step!=2)return 1;auto*y=spaceslug_output_projection_training_create(w.data(),H,T);if(!y||spaceslug_output_projection_training_update_adamw_state(y,cw.data(),cm.data(),cv.data(),1)!=0||spaceslug_output_projection_training_adamw_step(y,a.data(),u.data(),R,lr,b1,b2,eps,decay)!=0)return 1;std::vector<float>continued(w.size());if(spaceslug_output_projection_training_readback_adamw_state(y,continued.data(),rg.data(),rm.data(),rv.data(),&step)!=0||step!=2)return 1;float ep=0;for(size_t i=0;i<w.size();++i)ep=std::max(ep,std::abs(continued[i]-uninterrupted[i]));spaceslug_output_projection_training_destroy(y);spaceslug_output_projection_training_destroy(x);if(e1>5e-5f||ep>5e-5f){std::cerr<<"Output projection AdamW parity mismatch one="<<e1<<" checkpoint="<<ep<<'\n';return 1;}std::cout<<"Standalone output projection AdamW checkpoint parity: PASS max_error="<<std::max(e1,ep)<<'\n';return 0;}
